    "t_ar": "تجربة: ميزان الغضب",
    "t_en": "Experiment: The Anger Thermometer",
    "lead_ar": "مجموعات من أربعة. أمامكم مواقف مدرسية على بطاقات، وميزانٌ من 1 إلى 5.",
    "rounds_ar": [
     [
      "5 دقائق",
      "الجولة 1",
      "اقرؤوا كل موقف وضعوه على الميزان: كم يُغضبكم؟ ستختلفون، وهذا هو المطلوب."
     ],
     [
      "5 دقائق",
      "الجولة 2",
      "لكل موقف: ما علامة الجسد التي ستظهر أولاً؟"
     ],
     [
      "5 دقائق",
      "الجولة 3",
      "اختاروا أشدّ المواقف درجة، واكتبوا له ردّين مختلفين ممكنين."
     ]
    ],
    "i_ar": "المقصود من الجولة الأولى أن يروا الاختلاف: الموقف الواحد درجةُ غضبه تختلف من شخص لآخر، فلا صواب ولا خطأ هنا. وفي الجولة الثالثة لا تقبل ردّاً واحداً؛ اطلب الثاني ولو كان أضعف.",
    "m_ar": "بطاقات المواقف، ورقة الميزان، أقلام",
